components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; box-sizing: border-box; border-radius: var(--radius, 0.5rem); font: 500 0.8125rem/1.5 var(--font-sans, Poppins, system-ui, sans-serif); text-decoration: none; white-space: nowrap; transition: all var(--duration, 150ms) cubic-bezier(0.4, 0, 0.2, 1); --ds-shadow: var(--shadow, 0 8px 24px hsl(216 33% 13% / 0.12)); height: 3rem; padding: 0 2rem; color: hsl(var(--primary-foreground, 216 33% 13%)); background: hsl(var(--primary, 36.575 100% 71.373%)); box-shadow: var(--ds-shadow); }
.ds-button-primary:hover { background: hsl(var(--primary-hover, 36.585 100% 83.922%)); }
.ds-button-primary svg { width: 1rem; height: 1rem; flex-shrink: 0; }
.ds-button-primary:focus-visible { outline: none; box-shadow: 0 0 0 2px hsl(var(--ring, 36.575 100% 71.373%)), var(--ds-shadow, 0 0 transparent); }
.ds-button-primary:active { transform: translateY(1px); }
@media (prefers-reduced-motion: reduce) { .ds-button-primary:active { transform: none; } }

.ds-button-ghost { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; box-sizing: border-box; border-radius: var(--radius, 0.5rem); font: 500 0.8125rem/1.5 var(--font-sans, Poppins, system-ui, sans-serif); text-decoration: none; white-space: nowrap; transition: all var(--duration, 150ms) cubic-bezier(0.4, 0, 0.2, 1); min-height: 44px; padding: 0.5rem; color: hsl(var(--text-primary, 215 45% 96%)); background: transparent; }
.ds-button-ghost:hover { color: hsl(var(--accent-foreground, 215 45% 96%)); background: hsl(var(--accent, 214 25% 31%)); }
@media (min-width: 40rem) { .ds-button-ghost { padding-inline: 0.75rem; } }
.ds-button-ghost svg { width: 1rem; height: 1rem; flex-shrink: 0; }
.ds-button-ghost:focus-visible { outline: none; box-shadow: 0 0 0 2px hsl(var(--ring, 36.575 100% 71.373%)), var(--ds-shadow, 0 0 transparent); }
.ds-button-ghost:active { transform: translateY(1px); }
@media (prefers-reduced-motion: reduce) { .ds-button-ghost:active { transform: none; } }

.ds-app-bar { background: hsl(var(--surface-secondary, 214 28% 27%)); border-bottom: 1px solid hsl(var(--border-primary, 214 22% 65%)); }
.ds-nav { max-width: 72rem; box-sizing: border-box; margin-inline: auto; padding-inline: 1rem; }
.ds-nav-list { display: flex; flex-wrap: wrap; align-items: center; gap: 0.125rem; list-style: none; margin: 0; padding: 0.5rem 0; }
.ds-nav-link { display: inline-flex; min-height: 44px; align-items: center; padding-inline: 0.5rem; border-radius: var(--radius, 0.5rem); color: hsl(var(--text-secondary, 215 29% 78%)); font: 500 0.8125rem/1.5 var(--font-sans, Poppins, system-ui, sans-serif); text-decoration: none; white-space: nowrap; }
.ds-nav-link:hover, .ds-nav-link[aria-current="page"] { background: hsl(var(--surface-primary, 214.286 31.111% 17.647%)); color: hsl(var(--text-action, 36.575 100% 71.373%)); }
.ds-nav-link:focus-visible { outline: 2px solid hsl(var(--ring, 36.575 100% 71.373%)); outline-offset: 2px; }
@media (min-width: 40rem) { .ds-nav { padding-inline: 1.5rem; } .ds-nav-list { gap: 0.5rem; } .ds-nav-link { padding-inline: 0.75rem; } }

.ds-card { display: flex; flex-direction: column; overflow: hidden; border-radius: var(--radius-lg, 0.75rem); background: hsl(var(--surface-raised, 214 28% 27%)); color: hsl(var(--text-primary, 215 45% 96%)); }
.ds-card-media { display: block; width: 100%; height: auto; aspect-ratio: 1200 / 630; object-fit: cover; }
.ds-card-content { display: flex; flex: 1; flex-direction: column; padding: 1.25rem; }
.ds-card-title { margin: 0 0 0.5rem; font: 500 1.375rem/1.2 var(--font-sans, Poppins, system-ui, sans-serif); }
.ds-card-description { margin: 0 0 1rem; color: hsl(var(--text-secondary, 215 29% 78%)); font: 400 1rem/1.6 var(--font-sans, Poppins, system-ui, sans-serif); }
.ds-card-actions { display: flex; flex-wrap: wrap; gap: 0.5rem 1.25rem; margin-top: auto; }
.ds-card-link { display: inline-flex; min-height: 2rem; align-items: center; color: hsl(var(--text-action, 36.575 100% 71.373%)); font: 400 0.875rem/1.5 var(--font-sans, Poppins, system-ui, sans-serif); text-decoration: underline; text-underline-offset: 0.2em; }
.ds-card-link:hover { color: hsl(var(--primary-hover, 36.585 100% 83.922%)); }
.ds-card-link:focus-visible { outline: 2px solid; outline-offset: var(--focus-offset, 3px); }

.ds-card-link { display: inline-flex; min-height: 2rem; align-items: center; color: hsl(var(--text-action, 36.575 100% 71.373%)); font: 400 0.875rem/1.5 var(--font-sans, Poppins, system-ui, sans-serif); text-decoration: underline; text-underline-offset: 0.2em; }
.ds-card-link:hover { color: hsl(var(--primary-hover, 36.585 100% 83.922%)); }
.ds-card-link:focus-visible { outline: 2px solid; outline-offset: var(--focus-offset, 3px); }

.ds-about { color: hsl(var(--text-primary, 215 45% 96%)); }
.ds-about-marker { display: block; color: hsl(var(--text-action, 36.575 100% 71.373%)); font: 400 1.25rem/1.5 var(--workbench-font-code, "Source Code Pro", ui-monospace, Menlo, Consolas, monospace); }
.ds-about-keyword { color: hsl(var(--workbench-syntax-keyword, 27 78% 72%)); }
.ds-about-content { margin-block: 0.75rem; border-inline-start: 1px solid hsl(var(--border-primary, 214 22% 65%)); padding-block: 1.5rem; padding-inline-start: 1rem; }
.ds-about-name { margin: 0; font: 500 clamp(2.125rem, 5.6vw, 4.5rem)/1.1 var(--font-sans, Poppins, system-ui, sans-serif); letter-spacing: -0.04em; }
.ds-about-type { color: hsl(var(--workbench-syntax-type, 276 66% 82%)); }
.ds-about-role { margin: 0.75rem 0 0; font: 500 clamp(1.25rem, 3vw, 1.75rem)/1.2 var(--font-sans, Poppins, system-ui, sans-serif); }
@media (min-width: 40rem) { .ds-about-content { padding-block: 2rem; padding-inline-start: 2rem; } }
